// UpdateOutputOnly persists the server-owned fields of in that paths names, in
// one transaction guarded by in.Etag.
func (r *GormCommissionRepository) UpdateOutputOnly(ctx context.Context, in *commissionv1.Commission, paths []string) (*commissionv1.Commission, error) {
	key, err := r.rowKey(in.GetName())
	if err != nil {
		return nil, err
	}
	err = r.DB.Transaction(func(tx *gorm.DB) error { return r.updateOutputOnlyTx(ctx, tx, in, paths) })
	if err != nil {
		return nil, repox.MapGormErr(err)
	}
	return r.get(ctx, key)
}

// updateOutputOnlyTx is UpdateOutputOnly's write inside tx, which a Batch
// shares with other writes.
func (r *GormCommissionRepository) updateOutputOnlyTx(ctx context.Context, tx *gorm.DB, in *commissionv1.Commission, paths []string) error {
	if len(paths) == 0 {
		return fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		return err
	}
	{
		var existing commission.Commission
		// FOR UPDATE, as in updateTx: concurrent writers holding one etag
		// take turns, and only the first passes the guard.
		if err := tx.WithContext(ctx).Clauses(clause.Locking{Strength: "UPDATE"}).First(&existing, "name = ?", key).Error; err != nil {
			return err
		}
		if in.GetEtag() != "" && existing.Etag != nil && *existing.Etag != in.GetEtag() {
			return repox.ErrConflict
		}
		next := commission.CommissionFromProto(in)
		if repox.InMask(paths, "uid") {
			existing.UID = next.UID
		}
		if repox.InMask(paths, "expire_time") {
			existing.ExpireTime = next.ExpireTime
		}
		existing.Etag = repox.Ptr(repox.NewULID())
		return commission.NewCommissionStore(tx).Update(ctx, &existing)
	}
}

// newRow builds the row a Batch inserts for in under parent, and the
// record it stands for, named: the same resolution Create applies.
func (r *GormCommissionRepository) newRow(parent string, in *commissionv1.Commission) (*commission.Commission, *commissionv1.Commission, error) {
	parentIDs, err := repox.SplitName(parent, "hotels")
	if err != nil {
		return nil, nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "hotels", "commissions")
		if err != nil {
			return nil, nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return nil, nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*commissionv1.Commission)
	in.Name = FormatCommissionName(parentIDs[0], id)
	id = rowID // keyed as Create keys it
	m := commission.CommissionFromProto(in)
	m.ID = id
	m.Name = in.GetName()
	m.HotelID = parentIDs[0]
	m.Etag = repox.Ptr(repox.NewULID())
	return m, in, nil
}

